tool.command:
@PREPARE_INPUT_FILES@
#set $section = $sec_restrict
@PREPARE_TARGETS_FILE@
@PREPARE_REGIONS_FILE@

bcftools @EXECUTABLE@

## Query section
#set $section = $sec_query
  --format '${section.format}'

${section.allow_undef_tags}

${section.print_header}
${section.disable_automatic_newline}

#if str($section.print_filtered) != "":
  --print-filtered "${section.print_filtered}"
#end if

## Default section
#set $section = $sec_restrict
@INCLUDE@
@EXCLUDE@
@COLLAPSE@
@REGIONS@
@SAMPLES@
${section.force_samples}
@TARGETS@
@VERBOSITY@

## Primary Input/Outputs
--vcf-list @INPUT_LIST_FILE@
> $output_file
